", "new_string": "// kernelPackagePrefixes are the package names (or name prefixes) that provide
// the kernel image, the kernel modules or the kernel devel files.
// Packages such as kernel-tools, kernel-srpm-macros, perf, python-perf are not
// kernel packages: they are not bound to a concrete kernel release and have to
// be kept in the scan result whatever the running kernel is.
var kernelPackagePrefixes = []string{
	"kernel-core",
	"kernel-modules",
	"kernel-devel",
	"kernel-debug",
	"kernel-rt",
	"kernel-uek",
}

// isKernelPackage returns whether the package is a kernel package
// (kernel image, modules, devel, debug or rt variant).
func isKernelPackage(name string) bool {
	if name == "kernel" {
		return true
	}
	for _, prefix := range kernelPackagePrefixes {
		if strings.HasPrefix(name, prefix) {
			return true
		}
	}
	return false
}

// isDebugKernelPackage returns whether the kernel package is a debug variant.
func isDebugKernelPackage(name string) bool {
	return strings.Contains(name, "debug")
}

// isDebugRunningKernel returns whether the running kernel is a debug kernel.
func isDebugRunningKernel(kernelRelease string) bool {
	return strings.HasSuffix(kernelRelease, "debug")
}

// hasArchInKernelRelease returns whether the release string of the running
// kernel contains the architecture, e.g. "5.14.0-427.13.1.el9_4.x86_64".
// RHEL 6(or later), Alma, Rocky, Amazon, Fedora 9(or later) show the arch.
// If the distro release is unknown, the arch is expected (the modern format).
func hasArchInKernelRelease(family, release string) bool {
	switch family {
	case constant.RedHat, constant.CentOS, constant.Oracle:
		major, err := distroMajor(release)
		if err != nil {
			return true
		}
		return 6 <= major
	case constant.Fedora:
		major, err := distroMajor(release)
		if err != nil {
			return true
		}
		return 9 <= major
	}
	return true
}

func distroMajor(release string) (int, error) {
	fields := strings.Fields(release)
	if len(fields) == 0 {
		return 0, xerrors.Errorf("Release is empty: %s", release)
	}
	return strconv.Atoi(strings.Split(fields[0], ".")[0])
}

// isRunningKernel detects whether the package is a kernel package and whether
// it matches the running kernel. release is the distro release of the host
// (e.g. "8.9") because the format of the kernel release differs by the version.
func isRunningKernel(pack models.Package, family string, release string, kernel models.Kernel) (isKernel, running bool) {
	switch family {
	case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
		if pack.Name == "kernel-default" {
			// Remove the last period and later because uname don't show that.
			ss := strings.Split(pack.Release, ".")
			rel := strings.Join(ss[0:len(ss)-1], ".")
			ver := fmt.Sprintf("%s-%s-default", pack.Version, rel)
			return true, kernel.Release == ver
		}
		return false, false

	case constant.RedHat, constant.Oracle, constant.CentOS, constant.Alma, constant.Rocky, constant.Amazon, constant.Fedora:
		if !isKernelPackage(pack.Name) {
			return false, false
		}

		// A debug kernel is provided by the debug variants of the kernel packages
		// (kernel-debug, kernel-debug-core, kernel-debug-modules-extra, ...)
		// and a normal kernel by the non debug ones. They never match each other.
		kernelDebug := isDebugRunningKernel(kernel.Release)
		if kernelDebug != isDebugKernelPackage(pack.Name) {
			return true, false
		}

		modern := hasArchInKernelRelease(family, release)
		ver := fmt.Sprintf("%s-%s", pack.Version, pack.Release)
		if modern {
			ver = fmt.Sprintf("%s-%s.%s", pack.Version, pack.Release, pack.Arch)
		}
		if kernelDebug {
			if modern {
				ver += "+debug"
			} else {
				ver += "debug"
			}
		}
		return true, kernel.Release == ver

	default:
		logging.Log.Warnf("Reboot required is not implemented yet: %s, %v", family, kernel)
	}
	return false, false
}
