func TestTmpRunningKernelVariants(t *testing.T) {
	r := newAlma(config.ServerInfo{})
	r.Distro = config.Distro{Family: constant.Alma, Release: "9.4"}
	r.Kernel = models.Kernel{Release: "5.14.0-427.13.1.el9_4.x86_64+debug"}

	in := `openssl	0	3.0.1	37.el9_2	x86_64
kernel 0 5.14.0 427.13.1.el9_4 x86_64
kernel 0 5.14.0 427.18.1.el9_4 x86_64
kernel-core 0 5.14.0 427.13.1.el9_4 x86_64
kernel-modules 0 5.14.0 427.13.1.el9_4 x86_64
kernel-debug 0 5.14.0 427.13.1.el9_4 x86_64
kernel-debug 0 5.14.0 427.18.1.el9_4 x86_64
kernel-debug-core 0 5.14.0 427.13.1.el9_4 x86_64
kernel-debug-modules 0 5.14.0 427.13.1.el9_4 x86_64
kernel-debug-modules-extra 0 5.14.0 427.13.1.el9_4 x86_64
kernel-tools 0 5.14.0 427.18.1.el9_4 x86_64
kernel-srpm-macros 0 1.0 84.el9 noarch
kernel-livepatch-tools 0 11.0 1.el9 x86_64
perf 0 5.14.0 427.18.1.el9_4 x86_64
python-perf 0 5.14.0 427.18.1.el9_4 x86_64`

	packs, _, err := r.parseInstalledPackages(in)
	if err != nil {
		t.Fatal(err)
	}

	wantRunning := []string{
		"kernel-debug",
		"kernel-debug-core",
		"kernel-debug-modules",
		"kernel-debug-modules-extra",
	}
	for _, n := range wantRunning {
		p, ok := packs[n]
		if !ok {
			t.Errorf("%s: not collected", n)
			continue
		}
		if p.Release != "427.13.1.el9_4" {
			t.Errorf("%s: expected release 427.13.1.el9_4, actual %s", n, p.Release)
		}
		if p.Arch != "x86_64" {
			t.Errorf("%s: expected arch x86_64, actual %s", n, p.Arch)
		}
	}

	notWant := []string{"kernel", "kernel-core", "kernel-modules"}
	for _, n := range notWant {
		if _, ok := packs[n]; ok {
			t.Errorf("%s: must not be collected (not the running kernel)", n)
		}
	}

	always := []string{"openssl", "kernel-tools", "kernel-srpm-macros", "kernel-livepatch-tools", "perf", "python-perf"}
	for _, n := range always {
		if _, ok := packs[n]; !ok {
			t.Errorf("%s: accessory package must always remain", n)
		}
	}
}

func TestTmpRunningKernelAmazon(t *testing.T) {
	r := newAmazon(config.ServerInfo{})
	r.Distro = config.Distro{Family: constant.Amazon, Release: "2"}
	r.Kernel = models.Kernel{Release: "5.10.102-99.485.amzn2.x86_64"}

	in := `kernel 0 5.10.102 99.485.amzn2 x86_64
kernel 0 5.10.110 102.510.amzn2 x86_64
kernel-tools 0 5.10.110 102.510.amzn2 x86_64
amazon-ssm-agent 0 3.1.13.0 1.amzn2 x86_64`

	packs, _, err := r.parseInstalledPackages(in)
	if err != nil {
		t.Fatal(err)
	}
	if p := packs["kernel"]; p.Release != "99.485.amzn2" {
		t.Errorf("kernel: expected 99.485.amzn2, actual %s", p.Release)
	}
	if _, ok := packs["kernel-tools"]; !ok {
		t.Errorf("kernel-tools must remain")
	}
	if _, ok := packs["amazon-ssm-agent"]; !ok {
		t.Errorf("amazon-ssm-agent must remain")
	}
}
